#' Plot Speaker Landscapes
#'
#' Takes the UMAP coordinates generated by \code{make_speaker_landscapes} and creates
#' a scatter plot visualizing the distribution of speakers, optionally colored
#' by category, cluster, or cosine distance from a concept centroid, with optional HDBSCAN
#' cluster circles and key word token labels.
#'
#' @param speaker_landscape A \code{list} object returned by the \code{make_speaker_landscapes}
#'   function, containing the UMAP-reduced coordinates for speakers (\code{$speakers})
#'   and all mapped tokens (\code{$all_tokens}).
#' @param tokens_to_plot A data frame or tibble with a column named \code{token}
#'   (or a character vector) containing tokens (e.g., important words) to display as text labels. Defaults to \code{NULL}.
#' @param size_points A numeric value specifying the size of the speaker points in the plot.
#'   Defaults to \code{1}.
#' @param alpha_points A numeric value specifying the transparency (alpha) of the
#'   speaker points in the plot. Defaults to \code{.6}.
#' @param categories Optional: A data frame or tibble with columns named \code{author}
#'   (containing speaker identifiers) and \code{categories} (containing the classification
#'   of the speakers). If provided, speakers can be colored by this column.
#'   Defaults to \code{NULL}.
#' @param centroid Optional numeric vector or \code{dictionary_centroid} object (from
#'   \code{\link{compute_dictionary_centroid}}). If supplied alongside \code{embedding},
#'   calculates the normalized cosine proximity from each speaker to this centroid and colors the points accordingly.
#' @param dictionary Optional dictionary of tokens (e.g., anger tokens). If supplied alongside \code{embedding},
#'   its centroid is computed automatically and used to color points by cosine proximity.
#' @param embedding Optional vector embeddings matrix, \code{word2vec} model, or file path to an .emb file.
#'   Required if \code{centroid} or \code{dictionary} is provided.
#' @param color_by Character string specifying how to color speaker points:
#'   \code{"auto"} (default: colors by proximity if available, otherwise by category, or by cluster if clusters are present),
#'   \code{"proximity"} (continuous gradient of cosine proximity to centroid),
#'   \code{"category"} (discrete categories),
#'   \code{"cluster"} (HDBSCAN clusters from \code{\link{extract_speaker_clusters}}), or \code{"none"}.
#'   (\code{"distance"} is also accepted for backward compatibility).
#' @param proximity_palette Character string specifying the color palette for proximity:
#'   a viridis palette (\code{"viridis"} (default), \code{"plasma"}, \code{"magma"}, \code{"inferno"}, \code{"cividis"}, \code{"turbo"}),
#'   a ColorBrewer palette (\code{"Spectral"}, \code{"RdYlBu"}, \code{"Blues"}), or a custom vector of colors.
#' @param distance_palette Alias for \code{proximity_palette} for backward compatibility. Defaults to \code{NULL}.
#' @param legend_title Optional character string specifying a custom title for the plot legend.
#'   If \code{NULL} (default), uses the variable name of the aesthetic being plotted (e.g., \code{"centroid_proximity"}, \code{"categories"}, or \code{"cluster"}).
#' @param show_clusters Logical or \code{"auto"}. If \code{TRUE} (or \code{"auto"} when \code{speaker_landscape$clusters} is present),
#'   draws a circle around each HDBSCAN cluster on the 2D landscape whose size (radius) depends on the
#'   locations of its member speakers on the 2D plot. If \code{TRUE} and clusters have not yet been extracted,
#'   \code{\link{extract_speaker_clusters}} is called automatically with \code{minPts = cluster_minPts}.
#' @param cluster_minPts Integer specifying \code{minPts} if \code{\link{extract_speaker_clusters}} is called
#'   automatically when \code{show_clusters = TRUE} or \code{color_by = "cluster"}. Defaults to \code{5}.
#' @param cluster_alpha Numeric value in \code{[0, 1]} specifying the fill opacity of the cluster circles/ellipses.
#'   Defaults to \code{0} (unfilled outline circles).
#' @param cluster_color Optional color (or vector of colors) for the cluster circles. If \code{NULL} (default),
#'   clusters are colored distinctly using a consistent palette, while noise points are colored gray.
#' @param noise_color Color string used for speakers assigned to the noise category (\code{"Noise"}).
#'   Defaults to \code{"#9ca3af"} (gray).
#' @param label_clusters Logical. If \code{TRUE}, displays cluster labels at the center of each cluster circle.
#'   Defaults to \code{FALSE}.
#' @param interactive Logical. If \code{TRUE}, returns an interactive plot with click-to-view
#'   speaker text inspection via \code{\link{plot_interactive_landscape}}. Defaults to \code{FALSE}.
#' @param ... Additional arguments passed to \code{\link{plot_interactive_landscape}} when \code{interactive = TRUE}.
#'
#' @return A \code{ggplot} object (if \code{interactive = FALSE}) or an interactive HTML widget (if \code{interactive = TRUE}).
#'
#' @importFrom ggplot2 ggplot aes geom_point geom_text geom_polygon geom_path coord_fixed theme_minimal theme element_blank scale_color_viridis_c scale_color_gradientn scale_color_distiller scale_color_manual scale_fill_manual labs guides guide_legend
#' @importFrom dplyr %>% mutate left_join filter rename bind_rows
#' @importFrom tibble tibble
#'
#' @examples
#' \dontrun{
#' library(ggplot2)
#' library(dplyr)
#'
#' # Setup dummy data matching make_speaker_landscapes output
#' landscape_data <- list(
#'   speakers = tibble::tibble(author = c("a", "b", "c", "d"), n_quotes = 10, X1 = 1:4, X2 = 4:1),
#'   all_tokens = tibble::tibble(
#'     token = c("a", "b", "c", "d", "cat", "dog"),
#'     X1 = c(1:4, 2.5, 3.5),
#'     X2 = c(4:1, 3.5, 2.5)
#'   )
#' )
#'
#' # Example 1: Basic static plot
#' plot_speaker_landscapes(landscape_data)
#'
#' # Example 2: Interactive plot with click-to-view text
#' plot_speaker_landscapes(landscape_data, interactive = TRUE)
#' }
#' @export
plot_speaker_landscapes <- function(speaker_landscape,
                                    tokens_to_plot = NULL,
                                    size_points = 1,
                                    alpha_points = .6,
                                    categories = NULL,
                                    centroid = NULL,
                                    dictionary = NULL,
                                    embedding = NULL,
                                    color_by = c("auto", "proximity", "category", "cluster", "distance", "none"),
                                    proximity_palette = "viridis",
                                    distance_palette = NULL,
                                    legend_title = NULL,
                                    show_clusters = "auto",
                                    cluster_minPts = 5,
                                    cluster_alpha = 0,
                                    cluster_color = NULL,
                                    noise_color = "#9ca3af",
                                    label_clusters = FALSE,
                                    interactive = FALSE,
                                    ...) {
  color_by <- match.arg(color_by)

  # Support distance_palette as alias for proximity_palette
  if (!is.null(distance_palette)) {
    proximity_palette <- distance_palette
  }

  # If dictionary is provided, compute centroid
  if (!is.null(dictionary)) {
    if (is.null(embedding)) {
      stop("`embedding` must be provided when `dictionary` is specified.")
    }
    centroid <- compute_dictionary_centroid(dictionary, embedding)
  }

  # If centroid is provided, calculate speaker proximity
  if (!is.null(centroid)) {
    if (is.null(embedding)) {
      stop("`embedding` must be provided when `centroid` is specified.")
    }
    speaker_landscape <- calculate_centroid_proximity(
      speaker_landscape = speaker_landscape,
      centroid = centroid,
      embedding = embedding
    )
    if (color_by %in% c("auto", "distance")) {
      color_by <- "proximity"
    }
  }

  # Check if clusters exist or need to be computed
  has_clusters <- !is.null(speaker_landscape$clusters) || "cluster" %in% colnames(speaker_landscape$speakers)
  if ((isTRUE(show_clusters) || color_by == "cluster") && !has_clusters) {
    speaker_landscape <- extract_speaker_clusters(
      speaker_landscape = speaker_landscape,
      minPts = cluster_minPts,
      embedding = embedding
    )
    has_clusters <- TRUE
  }

  draw_clusters <- if (identical(show_clusters, "auto")) {
    !is.null(speaker_landscape$clusters) && nrow(speaker_landscape$clusters) > 0
  } else {
    isTRUE(show_clusters)
  }

  if (isTRUE(interactive)) {
    return(plot_interactive_landscape(
      speaker_landscape = speaker_landscape,
      tokens_to_plot = tokens_to_plot,
      categories = categories,
      color_by = color_by,
      proximity_palette = proximity_palette,
      legend_title = legend_title,
      show_clusters = draw_clusters,
      cluster_minPts = cluster_minPts,
      cluster_alpha = cluster_alpha,
      cluster_color = cluster_color,
      noise_color = noise_color,
      label_clusters = label_clusters,
      size_points = if (size_points == 1) 7 else size_points,
      alpha_points = alpha_points,
      ...
    ))
  }

  # Extract speaker data
  df_final <- speaker_landscape$speakers
  clusters_df <- speaker_landscape$clusters

  # If cluster column exists in df_final but clusters_df was not precomputed, compute summary
  if (draw_clusters && (is.null(clusters_df) || nrow(clusters_df) == 0) && "cluster" %in% colnames(df_final)) {
    clustered_sub <- df_final %>% dplyr::filter(cluster > 0)
    if (nrow(clustered_sub) > 0) {
      if (!"cluster_label" %in% colnames(clustered_sub)) {
        clustered_sub$cluster_label <- paste0("Cluster ", clustered_sub$cluster)
      }
      clusters_df <- clustered_sub %>%
        dplyr::group_by(cluster, cluster_label) %>%
        dplyr::summarise(
          n_speakers = dplyr::n(),
          center_x = mean(X1, na.rm = TRUE),
          center_y = mean(X2, na.rm = TRUE),
          radius = as.numeric(
            stats::quantile(
              sqrt((X1 - mean(X1, na.rm = TRUE))^2 + (X2 - mean(X2, na.rm = TRUE))^2),
              probs = 0.95,
              na.rm = TRUE
            )
          ) * 1.05,
          .groups = "drop"
        )
    }
  }

  # Ensure cluster_label exists if cluster column is present
  if ("cluster" %in% colnames(df_final) && !"cluster_label" %in% colnames(df_final)) {
    df_final$cluster_label <- ifelse(
      df_final$cluster == 0,
      "Noise",
      paste0("Cluster ", df_final$cluster)
    )
  }

  # Check available proximity or distance column
  prox_candidates <- grep("(_proximity|_distance)$", colnames(df_final), value = TRUE)
  if (length(prox_candidates) == 0 && any(c("centroid_proximity", "centroid_distance") %in% colnames(df_final))) {
    prox_candidates <- intersect(c("centroid_proximity", "centroid_distance"), colnames(df_final))
  }
  has_proximity <- length(prox_candidates) > 0
  prox_col <- if (has_proximity) prox_candidates[1] else NULL

  # Determine coloring mode if auto
  if (color_by == "auto") {
    if (has_proximity && is.null(categories)) {
      color_by <- "proximity"
    } else if (!is.null(categories)) {
      color_by <- "category"
    } else if ("cluster_label" %in% colnames(df_final)) {
      color_by <- "cluster"
    } else if (has_proximity) {
      color_by <- "proximity"
    } else {
      color_by <- "none"
    }
  } else if (color_by == "distance") {
    color_by <- "proximity"
  }

  # Handle word tokens extraction safely
  low_dim_words <- tibble::tibble(words = character(), X1 = numeric(), X2 = numeric())

  if (!is.null(tokens_to_plot)) {
    if (is.data.frame(tokens_to_plot) && "token" %in% colnames(tokens_to_plot)) {
      target_tokens <- tolower(tokens_to_plot$token)
    } else if (is.character(tokens_to_plot)) {
      target_tokens <- tolower(tokens_to_plot)
    } else {
      target_tokens <- character(0)
    }

    if (!is.null(speaker_landscape$all_tokens) && length(target_tokens) > 0) {
      low_dim_words <- speaker_landscape$all_tokens %>%
        dplyr::filter(tolower(token) %in% target_tokens) %>%
        dplyr::rename(words = token)
    }
  } else if (!is.null(speaker_landscape$words)) {
    low_dim_words <- speaker_landscape$words
  }

  # Handle optional categories join
  if (!is.null(categories)) {
    df_final <- df_final %>%
      dplyr::left_join(categories %>% dplyr::mutate(author = tolower(author)), by = "author")
    if (!"categories" %in% colnames(df_final)) {
      df_final$categories <- "Uncategorized"
    }
  } else if (!"categories" %in% colnames(df_final)) {
    df_final <- df_final %>% dplyr::mutate(categories = "Uncategorized")
  }

  # Ensure cluster_label factor order if present: Cluster 1, Cluster 2, ..., Noise
  cluster_color_map <- NULL
  if ("cluster_label" %in% colnames(df_final)) {
    all_cluster_labs <- unique(c(df_final$cluster_label, if (!is.null(clusters_df)) clusters_df$cluster_label else character(0)))
    cluster_color_map <- get_cluster_colors(all_cluster_labs, cluster_palette = cluster_color, noise_color = noise_color)
    df_final$cluster_label <- factor(df_final$cluster_label, levels = names(cluster_color_map))
    if (!is.null(clusters_df) && nrow(clusters_df) > 0) {
      clusters_df$cluster_label <- factor(clusters_df$cluster_label, levels = names(cluster_color_map))
    }
  }

  # --- Generate Plot ---
  plot_obj <- df_final %>%
    ggplot2::ggplot(ggplot2::aes(x = X1, y = X2))

  # Draw Cluster Circles on 2D landscape if requested
  if (draw_clusters && !is.null(clusters_df) && nrow(clusters_df) > 0) {
    circle_polys <- build_cluster_circle_polygons(clusters_df)
    circle_polys$cluster_label <- factor(circle_polys$cluster_label, levels = names(cluster_color_map))

    if (cluster_alpha > 0) {
      if (!is.null(cluster_color) && length(cluster_color) == 1) {
        plot_obj <- plot_obj +
          ggplot2::geom_polygon(
            data = circle_polys,
            mapping = ggplot2::aes(x = x, y = y, group = cluster_label),
            inherit.aes = FALSE,
            fill = cluster_color,
            color = cluster_color,
            alpha = cluster_alpha,
            linewidth = 0.6
          )
      } else if (color_by %in% c("cluster", "none")) {
        plot_obj <- plot_obj +
          ggplot2::geom_polygon(
            data = circle_polys,
            mapping = ggplot2::aes(x = x, y = y, group = cluster_label, fill = cluster_label, color = cluster_label),
            inherit.aes = FALSE,
            alpha = cluster_alpha,
            linewidth = 0.6,
            show.legend = (color_by == "none")
          )
      } else {
        plot_obj <- plot_obj +
          ggplot2::geom_polygon(
            data = circle_polys,
            mapping = ggplot2::aes(x = x, y = y, group = cluster_label, fill = cluster_label),
            inherit.aes = FALSE,
            color = "#475569",
            alpha = cluster_alpha,
            linewidth = 0.5
          ) +
          ggplot2::labs(fill = "Cluster")
      }
    } else {
      # No fill: draw outline paths only
      if (!is.null(cluster_color) && length(cluster_color) == 1) {
        plot_obj <- plot_obj +
          ggplot2::geom_path(
            data = circle_polys,
            mapping = ggplot2::aes(x = x, y = y, group = cluster_label),
            inherit.aes = FALSE,
            color = cluster_color,
            linewidth = 0.7
          )
      } else if (color_by %in% c("cluster", "none")) {
        plot_obj <- plot_obj +
          ggplot2::geom_path(
            data = circle_polys,
            mapping = ggplot2::aes(x = x, y = y, group = cluster_label, color = cluster_label),
            inherit.aes = FALSE,
            linewidth = 0.7,
            show.legend = (color_by == "none")
          )
      } else {
        # When color_by is proximity or category, color circles by cluster palette or neutral gray
        plot_obj <- plot_obj +
          ggplot2::geom_path(
            data = circle_polys,
            mapping = ggplot2::aes(x = x, y = y, group = cluster_label),
            inherit.aes = FALSE,
            color = "#64748b",
            linewidth = 0.6
          )
      }
    }
  }

  # Determine effective legend title (custom text or variable name if NULL)
  eff_legend_title <- if (!is.null(legend_title)) {
    as.character(legend_title)
  } else if (color_by == "proximity" && has_proximity) {
    prox_col
  } else if (color_by == "category") {
    "categories"
  } else if (color_by == "cluster") {
    "cluster"
  } else {
    NULL
  }

  # Plot Speaker Points according to color_by
  if (color_by == "proximity" && has_proximity) {
    plot_obj <- plot_obj +
      ggplot2::geom_point(ggplot2::aes(color = .data[[prox_col]]), size = size_points, alpha = alpha_points)

    viridis_opts <- c("viridis", "plasma", "inferno", "magma", "cividis", "turbo", "rocket", "mako", "a", "b", "c", "d", "e", "f", "g", "h")
    if (length(proximity_palette) == 1 && tolower(proximity_palette) %in% viridis_opts) {
      plot_obj <- plot_obj +
        ggplot2::scale_color_viridis_c(name = eff_legend_title, option = tolower(proximity_palette))
    } else if (length(proximity_palette) > 1) {
      plot_obj <- plot_obj +
        ggplot2::scale_color_gradientn(name = eff_legend_title, colours = proximity_palette)
    } else {
      plot_obj <- plot_obj +
        tryCatch(
          ggplot2::scale_color_distiller(name = eff_legend_title, palette = proximity_palette),
          error = function(e) ggplot2::scale_color_viridis_c(name = eff_legend_title, option = "viridis")
        )
    }
  } else if (color_by == "category" && !is.null(categories)) {
    plot_obj <- plot_obj +
      ggplot2::geom_point(ggplot2::aes(color = categories), size = size_points, alpha = alpha_points) +
      ggplot2::labs(color = eff_legend_title)
  } else if (color_by == "cluster" && "cluster_label" %in% colnames(df_final)) {
    plot_obj <- plot_obj +
      ggplot2::geom_point(ggplot2::aes(color = cluster_label), size = size_points, alpha = alpha_points) +
      ggplot2::scale_color_manual(values = cluster_color_map, drop = FALSE) +
      ggplot2::labs(color = eff_legend_title)
    if (cluster_alpha > 0) {
      plot_obj <- plot_obj +
        ggplot2::scale_fill_manual(values = cluster_color_map, drop = FALSE) +
        ggplot2::guides(fill = "none")
    }
  } else {
    plot_obj <- plot_obj +
      ggplot2::geom_point(color = "#3b82f6", size = size_points, alpha = alpha_points)
  }

  # Add Cluster Labels at circle centers if requested
  if (draw_clusters && isTRUE(label_clusters) && !is.null(clusters_df) && nrow(clusters_df) > 0) {
    plot_obj <- plot_obj +
      ggplot2::geom_text(
        data = clusters_df,
        mapping = ggplot2::aes(x = center_x, y = center_y, label = cluster_label),
        inherit.aes = FALSE,
        fontface = "bold",
        color = "#1e293b",
        size = 3.8
      )
  }

  # Add Word Labels if available
  if (nrow(low_dim_words) > 0) {
    plot_obj <- plot_obj +
      ggplot2::geom_text(
        data = low_dim_words,
        mapping = ggplot2::aes(x = X1, y = X2, label = words),
        inherit.aes = FALSE,
        check_overlap = TRUE,
        color = "black",
        size = 4,
        alpha = 1
      )
  }

  # Apply Theme
  has_legend <- (color_by == "proximity" && has_proximity) ||
    (color_by == "category" && !is.null(categories)) ||
    (color_by == "cluster" && "cluster_label" %in% colnames(df_final)) ||
    (draw_clusters && is.null(cluster_color))

  plot_obj <- plot_obj +
    ggplot2::theme_minimal() +
    ggplot2::theme(
      panel.grid.major = ggplot2::element_blank(),
      panel.grid.minor = ggplot2::element_blank(),
      panel.border = ggplot2::element_blank(),
      axis.line = ggplot2::element_blank(),
      axis.title.x = ggplot2::element_blank(),
      axis.text.x = ggplot2::element_blank(),
      axis.ticks.x = ggplot2::element_blank(),
      axis.title.y = ggplot2::element_blank(),
      axis.text.y = ggplot2::element_blank(),
      axis.ticks.y = ggplot2::element_blank(),
      legend.position = if (has_legend) "right" else "none"
    )

  return(plot_obj)
}
